// Background music and sound effects, generated by code (no files, no licenses, free).
//  - music: a calm, slow chord loop (soft pad + gentle piano-like arpeggio + bass), ducked under the voice
//           and rising a little in pauses and on the end card.
//  - sfx:   soft pop when something appears, swipe for the highlighter, whoosh between scenes,
//           ding when an answer lands or a counter stops.
// Levels are set relative to the narration's own loudness, so it works with any recording.
// Settings: settings.yaml → sound (also in the app: Settings → Music and sound effects).
import fs from "node:fs";
import path from "node:path";
import { spawnSync } from "node:child_process";
import { P, readYaml } from "./core.mjs";

const SR = 44100;
const TAU = Math.PI * 2;
const db = (x) => Math.pow(10, x / 20);
const LEVEL = { off: 0, quiet: 0.6, normal: 1, louder: 1.5 };

export function soundSettings() {
  const s = readYaml(path.join(P.root, "settings.yaml"), {})?.sound ?? {};
  return { music: s.music ?? "normal", sfx: s.sfx ?? "normal" };
}

// deterministic "random" so every build of the same video sounds the same
function rnd(i) { const x = Math.sin(i * 127.1 + 311.7) * 43758.5453; return x - Math.floor(x); }
const midiHz = (m) => 440 * Math.pow(2, (m - 69) / 12);

// ---------------------------------------------------------------- narration envelope
/** Narration loudness every 20 ms (mono RMS), via FFmpeg. */
function narrationRms(file, total) {
  const blocks = Math.ceil(total / 0.02);
  const out = new Float32Array(blocks);
  if (!file || !fs.existsSync(file)) return { rms: out, speech: 0.1, has: false };
  const r = spawnSync("ffmpeg", ["-v", "error", "-i", file, "-ac", "1", "-ar", "8000", "-f", "f32le", "-"], { maxBuffer: 1 << 30 });
  if (r.status !== 0 || !r.stdout?.length) return { rms: out, speech: 0.1, has: false };
  const x = new Float32Array(r.stdout.buffer, r.stdout.byteOffset, Math.floor(r.stdout.length / 4));
  const per = 160; // 20 ms at 8 kHz
  for (let b = 0; b < blocks; b++) {
    let s = 0, n = 0;
    for (let i = b * per; i < Math.min(x.length, (b + 1) * per); i++) { s += x[i] * x[i]; n++; }
    out[b] = n ? Math.sqrt(s / n) : 0;
  }
  const sorted = [...out].filter((v) => v > 0).sort((a, b) => a - b);
  const p95 = sorted[Math.floor(sorted.length * 0.95)] ?? 0.1;
  const active = sorted.filter((v) => v > p95 * 0.2);
  const speech = active.length ? Math.sqrt(active.reduce((s, v) => s + v * v, 0) / active.length) : 0.1;
  return { rms: out, speech, has: true, gate: p95 * 0.2 };
}

/** Gain curve for the music (per 20 ms block): low under speech, higher in pauses longer than ~0.8 s. */
function duckCurve(env, total, endCardStart) {
  const n = env.rms.length;
  const talking = new Uint8Array(n);
  if (env.has) for (let i = 0; i < n; i++) if (env.rms[i] > env.gate) talking[i] = 1;
  // hold 0.8 s after speech (so short breaths don't pump), duck 0.15 s before it starts
  const held = new Uint8Array(n);
  for (let i = 0; i < n; i++) if (talking[i]) for (let k = Math.max(0, i - 8); k < Math.min(n, i + 40); k++) held[k] = 1;
  const g = new Float32Array(n);
  let v = db(-8);
  for (let i = 0; i < n; i++) {
    const t = i * 0.02;
    let target = env.has && held[i] ? db(-8) : 1;
    if (endCardStart != null && t >= endCardStart) target = Math.max(target, db(-4));
    const tau = target < v ? 0.12 : 0.9; // duck fast, recover slowly
    v += (target - v) * (1 - Math.exp(-0.02 / tau));
    g[i] = v;
  }
  // fade in 1.5 s, fade out the last 2.5 s
  for (let i = 0; i < n; i++) {
    const t = i * 0.02;
    g[i] *= Math.min(1, t / 1.5) * Math.min(1, Math.max(0, (total - t) / 2.5));
  }
  return g;
}

// ---------------------------------------------------------------- music
// Calm progression in C major: Cmaj7 – Am7 – Fmaj7 – G(add9), 76 BPM, one chord per bar.
const CHORDS = [
  { root: 36, notes: [60, 64, 67, 71] },
  { root: 33, notes: [57, 60, 64, 67] },
  { root: 29, notes: [53, 57, 60, 64] },
  { root: 31, notes: [55, 59, 62, 69] },
];
const BPM = 76, BEAT = 60 / BPM, BAR = BEAT * 4;

function music(total) {
  const N = Math.ceil(total * SR);
  const L = new Float32Array(N), R = new Float32Array(N);
  const bars = Math.ceil(total / BAR) + 1;
  for (let b = 0; b < bars; b++) {
    const ch = CHORDS[b % 4];
    const t0 = b * BAR;
    // pad: two slightly detuned sines per note, slow swell, overlapping the next bar
    for (const [k, m] of ch.notes.entries()) {
      const f = midiHz(m), pan = (k - 1.5) * 0.25;
      const s0 = Math.floor(t0 * SR), len = Math.floor((BAR + 1.2) * SR);
      for (let i = 0; i < len && s0 + i < N; i++) {
        const t = i / SR;
        const env = Math.min(1, t / 0.9) * Math.min(1, Math.max(0, (BAR + 1.2 - t) / 1.2));
        const v = (Math.sin(TAU * f * 1.0015 * t) + Math.sin(TAU * f * 0.9985 * t) + 0.25 * Math.sin(TAU * 2 * f * t)) * env * 0.05;
        L[s0 + i] += v * (1 - pan); R[s0 + i] += v * (1 + pan);
      }
    }
    // bass: root note, soft attack, held most of the bar
    {
      const f = midiHz(ch.root), s0 = Math.floor(t0 * SR), len = Math.floor(BAR * SR);
      for (let i = 0; i < len && s0 + i < N; i++) {
        const t = i / SR;
        const env = Math.min(1, t / 0.04) * (0.55 + 0.45 * Math.exp(-t * 1.5)) * Math.min(1, (BAR - t) / 0.3);
        const v = (Math.sin(TAU * f * t) + 0.2 * Math.sin(TAU * 2 * f * t)) * env * 0.16;
        L[s0 + i] += v; R[s0 + i] += v;
      }
    }
    // arpeggio: soft "felt piano" notes on the beat (an octave up); rests every 4th phrase so it breathes
    if (Math.floor(b / 4) % 4 !== 3) {
      const order = [0, 2, 1, 3];
      for (let q = 0; q < 4; q++) {
        if (q === 3 && rnd(b) < 0.5) continue;
        const m = ch.notes[order[q]] + 12, f = midiHz(m);
        const vel = 0.75 + 0.25 * rnd(b * 4 + q), pan = q % 2 ? 0.3 : -0.3;
        const s0 = Math.floor((t0 + q * BEAT) * SR), len = Math.floor(2.2 * SR);
        for (let i = 0; i < len && s0 + i < N; i++) {
          const t = i / SR;
          const env = Math.min(1, t / 0.006) * Math.exp(-t * 2.2);
          const v = (Math.sin(TAU * f * t) + 0.35 * Math.sin(TAU * 2 * f * t) * Math.exp(-t * 4) + 0.1 * Math.sin(TAU * 3 * f * t) * Math.exp(-t * 7)) * env * 0.06 * vel;
          L[s0 + i] += v * (1 - pan); R[s0 + i] += v * (1 + pan);
        }
      }
    }
  }
  // gentle low-pass (one pole, ~3 kHz) to keep it soft and out of the voice's way
  const a = Math.exp((-TAU * 3000) / SR);
  let yl = 0, yr = 0;
  for (let i = 0; i < N; i++) { yl = (1 - a) * L[i] + a * yl; yr = (1 - a) * R[i] + a * yr; L[i] = yl; R[i] = yr; }
  return [L, R];
}

// ---------------------------------------------------------------- sound effects
function noise(i) { return rnd(i * 1.37) * 2 - 1; }
const SFX = {
  pop(t) { const f = 900 * Math.exp(-t * 18) + 380; return Math.sin(TAU * f * t) * Math.exp(-t * 28) * Math.min(1, t / 0.002); },
  swipe(t, i) { return noise(i) * Math.sin(Math.PI * Math.min(1, t / 0.16)) * 0.5; },
  whoosh(t, i) { return noise(i) * Math.pow(Math.sin(Math.PI * Math.min(1, t / 0.45)), 2) * 0.5; },
  ding(t) { return [[1, 1, 1.4], [2.76, 0.45, 0.9], [5.4, 0.2, 0.5], [8.93, 0.08, 0.3]].reduce((s, [r, a, d]) => s + a * Math.sin(TAU * 1046.5 * r * t) * Math.exp(-t / d), 0) * Math.min(1, t / 0.003) * 0.6; },
  chime(t) { return [[1, 1, 1.8], [1.5, 0.5, 1.4], [2, 0.3, 1]].reduce((s, [r, a, d]) => s + a * Math.sin(TAU * 784 * r * t) * Math.exp(-t / d), 0) * Math.min(1, t / 0.004) * 0.45; },
};
const LEN = { pop: 0.25, swipe: 0.16, whoosh: 0.45, ding: 2.5, chime: 3 };
const GAIN = { pop: 1, swipe: 0.35, whoosh: 0.3, ding: 0.75, chime: 0.6 };
// band-pass sweeps for the noise-based effects (state-variable filter)
const SWEEP = { swipe: [2500, 5000], whoosh: [350, 2200] };

function sfxTrack(events, total) {
  const N = Math.ceil(total * SR);
  const L = new Float32Array(N), R = new Float32Array(N);
  for (const e of events) {
    const fn = SFX[e.kind]; if (!fn) continue;
    const s0 = Math.floor(e.t * SR), len = Math.floor(LEN[e.kind] * SR);
    const sw = SWEEP[e.kind];
    let lp = 0, bp = 0;
    for (let i = 0; i < len && s0 + i < N; i++) {
      if (s0 + i < 0) continue;
      const t = i / SR;
      let v = fn(t, s0 + i);
      if (sw) { // band-pass the noise, sweeping its centre
        const fc = sw[0] + (sw[1] - sw[0]) * (i / len), f = 2 * Math.sin((Math.PI * fc) / SR), q = 0.7;
        const hp = v - lp - q * bp; bp += f * hp; lp += f * bp; v = bp;
      }
      v *= GAIN[e.kind];
      const pan = e.kind === "whoosh" ? -0.5 + i / len : e.pan ?? 0;
      L[s0 + i] += v * (1 - pan * 0.6); R[s0 + i] += v * (1 + pan * 0.6);
    }
  }
  return [L, R];
}

/**
 * Turn the build's animation calls into sound-effect cues.
 * calls: [{fn, t, component, scene}] (absolute times); sceneStarts: [{t, index}]
 */
export function sfxEvents(calls, sceneStarts) {
  const ev = [];
  for (const s of sceneStarts) if (s.index > 0) ev.push({ kind: "whoosh", t: s.t - 0.12 });
  for (const c of calls) {
    if (c.fn === "pop") ev.push({ kind: c.component === "answer-box" ? "ding" : /end/.test(c.component) ? "chime" : "pop", t: c.t, pan: (rnd(c.t * 10) - 0.5) * 0.6 });
    else if (c.fn === "mark") ev.push({ kind: "swipe", t: c.t });
    else if (c.fn === "count") ev.push({ kind: "ding", t: c.t });
  }
  ev.sort((a, b) => a.t - b.t);
  // keep it tasteful: no two effects closer than 0.3 s (dings and chimes win), at most 3 pops in any 2 s
  const out = [];
  for (const e of ev) {
    const prev = out[out.length - 1];
    if (prev && e.t - prev.t < 0.3) {
      if ((e.kind === "ding" || e.kind === "chime") && prev.kind !== "ding" && prev.kind !== "chime") out[out.length - 1] = e;
      continue;
    }
    if (e.kind === "pop" && out.filter((x) => x.kind === "pop" && e.t - x.t < 2).length >= 3) continue;
    out.push(e);
  }
  return out;
}

function writeWav(file, L, R, gain = 1) {
  const N = L.length, buf = Buffer.alloc(44 + N * 4);
  buf.write("RIFF", 0); buf.writeUInt32LE(36 + N * 4, 4); buf.write("WAVE", 8); buf.write("fmt ", 12);
  buf.writeUInt32LE(16, 16); buf.writeUInt16LE(1, 20); buf.writeUInt16LE(2, 22); buf.writeUInt32LE(SR, 24);
  buf.writeUInt32LE(SR * 4, 28); buf.writeUInt16LE(4, 32); buf.writeUInt16LE(16, 34); buf.write("data", 36); buf.writeUInt32LE(N * 4, 40);
  const soft = (x) => (Math.abs(x) < 0.8 ? x : Math.sign(x) * (0.8 + 0.2 * Math.tanh((Math.abs(x) - 0.8) / 0.2)));
  for (let i = 0; i < N; i++) {
    buf.writeInt16LE(Math.round(soft(L[i] * gain) * 32767), 44 + i * 4);
    buf.writeInt16LE(Math.round(soft(R[i] * gain) * 32767), 46 + i * 4);
  }
  fs.writeFileSync(file, buf);
}
const rmsOf = (L) => { let s = 0; for (let i = 0; i < L.length; i += 7) s += L[i] * L[i]; return Math.sqrt(s / Math.ceil(L.length / 7)) || 1e-9; };

/**
 * Write music.wav and sfx.wav into outDir/assets. Returns <audio> tags for index.html.
 * o: {outDir, total, narration (file or null), calls, sceneStarts, endCardStart}
 */
export function buildSound(o) {
  const set = soundSettings();
  const mLevel = LEVEL[set.music] ?? 1, sLevel = LEVEL[set.sfx] ?? 1;
  const env = narrationRms(o.narration, o.total);
  let tags = "";
  if (mLevel > 0 && !o.skipMusic) {
    const [L, R] = music(o.total);
    // in pauses the music sits ~13 dB under the speaking voice; under speech another 8 dB lower
    const scale = (env.speech * db(-13) * mLevel) / rmsOf(L);
    const g = duckCurve(env, o.total, o.endCardStart);
    for (let i = 0; i < L.length; i++) { const k = g[Math.min(g.length - 1, Math.floor(i / SR / 0.02))] * scale; L[i] *= k; R[i] *= k; }
    writeWav(path.join(o.outDir, "assets", "music.wav"), L, R);
    tags += `\n    <audio id="music" src="assets/music.wav" data-start="0" data-duration="${o.total.toFixed(3)}" data-track-index="3" data-volume="1"></audio>`;
  }
  const events = sfxEvents(o.calls, o.sceneStarts);
  if (sLevel > 0 && events.length) {
    const [L, R] = sfxTrack(events, o.total);
    // effects sit ~10–12 dB under the voice: noticeable, never louder than the words
    writeWav(path.join(o.outDir, "assets", "sfx.wav"), L, R, env.speech * 1.1 * sLevel);
    tags += `\n    <audio id="sfx" src="assets/sfx.wav" data-start="0" data-duration="${o.total.toFixed(3)}" data-track-index="4" data-volume="1"></audio>`;
  }
  return { tags, events: events.length };
}
